L_values = range(1, 17)
C_L = {}
E_L = {}

for L in L_values:
    # Total count C_L (ignoring divisibility by 3)
    if L == 1:
        C_L[L] = 3
    else:
        # C_L = 3 * 4^(L-1)
        C_L[L] = 3 * (4**(L - 1))

    # Estimated count E_L (assuming uniform distribution mod 3)
    # E_L = C_L / 3 = 4^(L-1)
    E_L[L] = 4**(L - 1)

print("L | Total Count C_L | Estimated Count E_L")
print("-" * 40)
for L in L_values:
    print(f"{L:2} | {C_L[L]:<15} | {E_L[L]:<15}")
